        g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.18);
        o.connect(g); g.connect(master); o.start(); o.stop(ctx.currentTime + 0.2);
        setTimeout(blattTropfen, 80 + Math.random()*300);
