      lfo.frequency.value = 0.3 + Math.random() * 0.3;
      lfoG.gain.value = 200;
      lfo.connect(lfoG); lfoG.connect(bp.frequency); lfo.start(); nodes.push(lfo);
      // Einzelne Platscher
